use std::collections::{BTreeMap, BTreeSet};
use std::fs;
use std::path::{Path, PathBuf};

use crate::error::GenError;

/// The generated files of one crate, by path relative to the output folder.
///
/// The whole tree is built in memory before anything is written, so a failed build writes nothing.
#[derive(Debug, Clone, Default, PartialEq)]
pub struct OutputTree {
    files: BTreeMap<PathBuf, String>,
}

impl OutputTree {
    /// The first line of every generated file. A file on disk that starts with it is ours to replace
    /// or delete; any other file is hand-written and is left alone.
    pub const HEADER: &'static str = "// Generated by levi-ui-gen from design/tokens.json. Do not edit.";

    pub fn insert(&mut self, path: PathBuf, content: String) {
        self.files.insert(path, content);
    }

    pub fn get(&self, path: &Path) -> Option<&str> {
        self.files.get(path).map(String::as_str)
    }

    /// The relative paths, sorted.
    pub fn paths(&self) -> impl Iterator<Item = &Path> {
        self.files.keys().map(PathBuf::as_path)
    }

    pub fn len(&self) -> usize {
        self.files.len()
    }

    pub fn is_empty(&self) -> bool {
        self.files.is_empty()
    }

    /// The relative paths that writing would change: files that differ or are missing, and generated
    /// files on disk that this tree no longer produces. Sorted. Line ends do not count.
    pub fn diff(&self, root: &Path) -> Result<Vec<PathBuf>, GenError> {
        let mut changed = BTreeSet::new();
        for (path, content) in &self.files {
            if !Self::same_on_disk(&root.join(path), content)? {
                changed.insert(path.clone());
            }
        }
        changed.extend(self.stale(root)?);
        Ok(changed.into_iter().collect())
    }

    /// Writes the files that changed, deletes stale generated files, then removes folders that the
    /// deletes left empty.
    pub fn write_to(&self, root: &Path) -> Result<(), GenError> {
        for (path, content) in &self.files {
            let target = root.join(path);
            if Self::same_on_disk(&target, content)? {
                continue;
            }
            if let Some(parent) = target.parent() {
                fs::create_dir_all(parent).map_err(|source| GenError::Io { path: parent.to_path_buf(), source })?;
            }
            fs::write(&target, content).map_err(|source| GenError::Io { path: target.clone(), source })?;
        }
        for path in self.stale(root)? {
            let target = root.join(&path);
            fs::remove_file(&target).map_err(|source| GenError::Io { path: target.clone(), source })?;
            let mut folder = target.parent();
            while let Some(dir) = folder.filter(|dir| *dir != root) {
                let empty = fs::read_dir(dir).map(|mut entries| entries.next().is_none()).unwrap_or(false);
                if !empty || fs::remove_dir(dir).is_err() {
                    break;
                }
                folder = dir.parent();
            }
        }
        Ok(())
    }

    fn same_on_disk(path: &Path, content: &str) -> Result<bool, GenError> {
        match fs::read_to_string(path) {
            Ok(found) => Ok(found.replace("\r\n", "\n") == content.replace("\r\n", "\n")),
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(false),
            Err(source) => Err(GenError::Io { path: path.to_path_buf(), source }),
        }
    }

    /// Generated files under `root` that this tree does not produce.
    fn stale(&self, root: &Path) -> Result<Vec<PathBuf>, GenError> {
        let mut found = Vec::new();
        Self::collect_generated(root, root, &mut found)?;
        found.retain(|path| !self.files.contains_key(path));
        Ok(found)
    }

    fn collect_generated(root: &Path, dir: &Path, found: &mut Vec<PathBuf>) -> Result<(), GenError> {
        let entries = match fs::read_dir(dir) {
            Ok(entries) => entries,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return Ok(()),
            Err(source) => return Err(GenError::Io { path: dir.to_path_buf(), source }),
        };
        for entry in entries {
            let path = entry.map_err(|source| GenError::Io { path: dir.to_path_buf(), source })?.path();
            if path.is_dir() {
                Self::collect_generated(root, &path, found)?;
            } else if path.extension().is_some_and(|ext| ext == "rs")
                && Self::is_generated(&path)?
                && let Ok(relative) = path.strip_prefix(root)
            {
                found.push(relative.to_path_buf());
            }
        }
        Ok(())
    }

    fn is_generated(path: &Path) -> Result<bool, GenError> {
        let text = fs::read_to_string(path).map_err(|source| GenError::Io { path: path.to_path_buf(), source })?;
        Ok(text.lines().next().is_some_and(|first| first == Self::HEADER))
    }
}
